 r=work.evaluate(req,pol); assert r==want,(r,want)
chk({'layers':[{'b':False,'i':0,'s':''}]},p0,{'ok':True,'config':{'b':False,'i':0,'s':''},'error':None})
for key,val in [('b',0),('i',False),('s',1),('i',None)]: chk({'layers':[{key:val}]},p0,{'ok':False,'config':{},'error':'type'})
